mapper.sql:
where 1=1

		and cenc_llave = #{llaveTabla}


		and cenc_estado = #{estado}


		and cenc_nombre = #{nombre}


		and denc_fechainicio >= #{fechaInicioMin}


		and denc_fechainicio  <   #{fechaInicioMax}


		and denc_fechafin >= #{fechaFinMin}


		and denc_fechafin  <   #{fechaFinMax}


		and denc_fechaejecucion >= #{fechaEjecucionMin}


		and denc_fechaejecucion  <   #{fechaEjecucionMax}


		and benc_colaborativa = #{colaborativaFilter}


		and cenc_rol = #{rol}


		and cenc_cliente = #{cliente}


		and (upper(cenc_nombre) like upper('%' || #{filtroParametro} || '%'))
